struct sock *sctp6_create_sock(struct sock *sk, struct sctp_association *asoc, bool kern) {
    struct sock *new_sk;
    int err;

    /* Allocate a new socket */
    new_sk = sk_alloc(sk->sk_family, GFP_KERNEL, kern);
    if (!new_sk)
        return NULL;

    /* Initialize new socket with data from the existing socket */
    err = sctp_init_sock(new_sk, sk, asoc, kern);
    if (err) {
        sk_free(new_sk);
        return NULL;
    }

    /* Setup IPv6-specific parameters */
    if (sctp6_init_sock(new_sk, sk, asoc)) {
        sk_free(new_sk);
        return NULL;
    }

    return new_sk;
}

struct sock *sctp6_sock_create(struct sock *sk, struct sctp_association *asoc, bool kern)
{
    struct sock *new_sk;
    struct sctp6_sock *new_sctp6_sk;
    struct sctp6_sock *sctp6_sk = (struct sctp6_sock *)sk;

    new_sk = sock_alloc();
    if (!new_sk)
        return NULL;

    new_sctp6_sk = (struct sctp6_sock *)new_sk;

    /* Copy generic socket data */
    memcpy(new_sk, sk, sizeof(*sk));

    /* Initialize association */
    new_sctp6_sk->asoc = asoc;
    asoc->base.sk = new_sk;

    /* Copy IPv6 specific socket data */
    new_sctp6_sk->ipv6only = sctp6_sk->ipv6only;
    new_sctp6_sk->saddr = sctp6_sk->saddr;
    new_sctp6_sk->daddr = sctp6_sk->daddr;

    /* Initialize socket options and other settings */
    sock_init(new_sk);

    /* Setup socket for kernel use if needed */
    if (kern)
        new_sk->sk_flags |= SKF_KERNEL_SOCKET;

    return new_sk;
}

struct sock *sctp6_sock_create(struct sock *sk, struct sctp_association *asoc, bool kern)
{
    struct sock *new_sk;
    struct ipv6_pinfo *np, *newnp;

    new_sk = sk_clone(sk, GFP_KERNEL);
    if (!new_sk)
        return NULL;

    newnp = inet6_sk(new_sk);
    np = inet6_sk(sk);

    memcpy(newnp, np, sizeof(*newnp));

    new_sk->sk_asociation = *asoc;
    new_sk->sk_kernel = kern;

    if (sctp_sock_init(new_sk) < 0) {
        sock_put(new_sk);
        return NULL;
    }

    return new_sk;
}

struct sock *sctp6_sock_create(struct sock *sk, struct sctp_association *asoc, bool kern)
{
    struct sock *new_sk;
    struct sctp6_sock *new_sctp6_sk;

    new_sk = sk_clone(sk, GFP_KERNEL);
    if (!new_sk)
        return NULL;

    new_sctp6_sk = (struct sctp6_sock *)new_sk;

    new_sctp6_sk->sctp.asoc = *asoc;
    new_sctp6_sk->sctp.ep = sk->sk_prot->clone(sk, new_sk);
    if (!new_sctp6_sk->sctp.ep) {
        sock_put(new_sk);
        return NULL;
    }

    new_sctp6_sk->sctp.pf = sctp6_pf;
    new_sctp6_sk->sctp.options = sk->sk_options;

    new_sctp6_sk->sctp.ipv6.flags = 0;
    new_sctp6_sk->sctp.ipv6.otherscope = 0;
    new_sctp6_sk->sctp.ipv6.v6only = 1;

    if (kern)
        new_sctp6_sk->sctp.flags |= SCTP_SOCKET_TCP;

    return new_sk;
}

struct sock *sctp6_sock_create(struct sock *sk, struct sctp_association *asoc, bool kern) {
    struct sock *new_sk;
    struct sctp_sk *new_sctp_sk;
    int err;

    new_sk = sock_alloc();
    if (!new_sk)
        return NULL;

    sock_init_data(new_sk, NULL);
    new_sk->sk_family = AF_INET6;
    new_sk->sk_type = sk->sk_type;
    new_sk->sk_protocol = sk->sk_protocol;
    new_sk->sk_flags = sk->sk_flags;

    new_sctp_sk = sctp_sk(new_sk);
    new_sctp_sk->asoc = asoc;

    err = sctp_sock_options_copy(new_sk, sk);
    if (err < 0) {
        sock_release(new_sk);
        return NULL;
    }

    if (kern)
        new_sk->sk_kern = 1;

    return new_sk;
}
